head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[textbox > P > for]<br/>컴포넌트 클릭 시 포커스가 이동될 컴포넌트의 ID 를 설정합니다.",
    "validation" : [
        "클릭 시 포커스가 이동될 컴포넌트의 ID 를 문자열로 설정하여야 합니다.",
        "for 속성을 설정하면 tagname 속성값은 'label' 로 강제 적용되어야 합니다.",
        "존재하지 않는 ID 설정 시 동작하지 않아야 합니다.",
        "tabIndex 속성에 의한 순서는 무시되고 for 속성에 설정된 컴포넌트로 포커스가 이동되어야 합니다.",
        "포커스 이동 대상 컴포넌트가 포커스를 받을 수 없는 상태(Disabled 등)이면 포커스가 이동하지 않아야 합니다.",
        "Tab 키로 포커스를 이동할때는 적용되지 않아야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 기존 input2 있으면 삭제
    if (typeof input2 !== 'undefined') {
        input2.remove();
    }

    // 기존 button2 있으면 삭제
    if (typeof button2 !== 'undefined') {
        button2.remove();
    }

    // 기존 selectbox2 있으면 삭제
    if (typeof selectbox2 !== 'undefined') {
        selectbox2.remove();
    }

    // 조건 설정 (target)   
    let properties = {
        tabIndex: 2,
        for: con_for.getText(),
    };

    let cList = $c.gcm.createCList(properties);      

    // 조건 설정 (input)
    let properties_input = {
        tabIndex: 3,
    };

    let cList_input = $c.gcm.createCList(properties_input);    

    // 조건 설정 (button)
    let properties_button = {
        tabIndex: 4,
    };

    let cList_button = $c.gcm.createCList(properties_button);    

    // 조건 설정 (selectbox)
    let properties_selectbox = {
        tabIndex: 5,
    };

    let cList_selectbox = $c.gcm.createCList(properties_selectbox);    

    let grp_comp = $c.gcm.getTestGroup();

    let strNameSpace = $c.gcm.getNameSpace();
    let strStartComp = '';

    strStartComp += '<xf:input ' + strNameSpace + ' tabIndex="1" initValue="start" style="width:144px; height:21px;"></xf:input>';

    scwin.startcomp = await $p.dynamicCreate(
        "startcomp",
        "input",
        strStartComp,
        grp_comp
    );

    $c.gcm.createBasicInput(cList_input, 'ev:onfocus="scwin.input2_onfocus"', "input2");
    $c.gcm.createBasicButton(cList_button, 'ev:onfocus="scwin.button2_onfocus"', "button2");
    $c.gcm.createBasicSelectBox(cList_selectbox, 'ev:onfocus="scwin.selectbox2_onfocus"', "selectbox2");
    $c.gcm.createBasicTextBox(cList, 'ev:onfocus="scwin.target1_onfocus"')

    target1.setLabel("target");
    input2.setValue("input");
}



scwin.target1_onfocus = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("target1_onfocus");    
}



scwin.input2_onfocus = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("input2_onfocus");    
}



scwin.button2_onfocus = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("button2_onfocus");    
}



scwin.selectbox2_onfocus = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("selectbox2_onfocus");    
}



scwin.btn_setDisabled_onclick = function (e) {
    let cID = par_disabled.getText();

    $p.getComponentById(cID).setDisabled(true);
};



scwin.btn_setStartFocus_onclick = function (e) {    
    startcomp.focus();
};



scwin.btn_getTagName_onclick = function (e) {
    let rtn = '';

    rtn = target1.render.tagName
    wf_body_bottom.getObj("scwin").setReturnValue("tagName : " + rtn);        
};
